BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name,address,amenities,settings)values('ee610000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Readiness review SQL fixture','{"street":"1 Fixture Lane","city":"Fixture city","state":"XX"}',array['Supplied amenity'],'{"additionalUrls":[],"privateSetting":"PRIVATE-FIXTURE"}'),('ee610000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','Other readiness review SQL fixture','{}','{}','{}');
insert into public.property_contacts(id,property_id,contact_type,name,email,phone,is_primary,special_instructions,billing_address)values('ee610000-0000-4000-8000-000000000003','ee610000-0000-4000-8000-000000000001','primary','Public leasing contact','fixture@example.invalid','555-0100',true,'PRIVATE-FIXTURE','{"secret":"PRIVATE-FIXTURE"}'),('ee610000-0000-4000-8000-000000000004','ee610000-0000-4000-8000-000000000001','billing','PRIVATE-FIXTURE','billing@example.invalid',null,false,'PRIVATE-FIXTURE','{}');
insert into public.property_brand_assets(id,property_id,approval_status,generation_status,contract_hash,gemini_conversation_history)values('ee610000-0000-4000-8000-000000000005','ee610000-0000-4000-8000-000000000001','approved','complete',repeat('b',64),'[{"private":"PRIVATE-FIXTURE"}]');
insert into public.property_legal_configs(id,property_id,org_id,version,status,jurisdiction,legal_entity_name,effective_at,approved_by,approved_at,privacy_policy,terms,accessibility,fair_housing,pricing_disclaimer,analytics_consent,communications_consent)values('ee610000-0000-4000-8000-000000000006','ee610000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222',1,'approved','Fixture jurisdiction','Fixture entity','2026-01-01','11111111-1111-1111-1111-111111111111',clock_timestamp(),'{"text":"Supplied privacy statement"}','{"text":"Supplied terms"}','{"text":"Supplied accessibility"}','{"text":"Supplied Fair Housing"}','{"text":"Supplied pricing disclaimer"}','{"text":"Supplied analytics consent"}','{"text":"Supplied communications consent"}');
insert into public.integration_credentials(id,property_id,platform,status,credentials,notes,field_mapping)values('ee610000-0000-4000-8000-000000000007','ee610000-0000-4000-8000-000000000001','hubspot','pending','{"token":"PRIVATE-FIXTURE"}','PRIVATE-FIXTURE','{"private":"PRIVATE-FIXTURE"}');
create function pg_temp.read_check(b jsonb default'{}',p uuid default'ee610000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.read_readiness_reviews(p,'11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.decide(i uuid,b jsonb,calc jsonb default null,p uuid default'ee610000-0000-4000-8000-000000000001')returns jsonb language sql as $$select public.decide_readiness_review(i,p,'11111111-1111-1111-1111-111111111111',b,calc)$$;
create function pg_temp.build_input(caps jsonb default'[]')returns jsonb language sql as $$select jsonb_build_object('operation','build','enabledCapabilities',caps,'reason','Build exact source evidence for review')$$;
-- Service calculation fixture; browser/API never accepts this parameter.
create function pg_temp.calculation(caps jsonb default'[]')returns jsonb language plpgsql as $$
declare b jsonb:=public.readiness_source_bundle('ee610000-0000-4000-8000-000000000001');f jsonb:=b->'sources';p jsonb;reports jsonb;conflicts jsonb;
begin
 p:=jsonb_build_object('property',f->'property','contacts',f->'contacts','brand',coalesce(nullif(f->'brand','null'),'{}'),'assets',f->'assets','units',f->'units','pointsOfInterest',f->'pointsOfInterest','legal',f->'legal','integrations',f->'integrations','analyticsDestinations','[]'::jsonb,'chatbotContext',f->'chatbotContext','requestedCapabilities',caps,'enabledCapabilities','[]'::jsonb,'additionalUrls','[]'::jsonb,'readinessEvidence',jsonb_build_object('sourceHash',b->>'sourceHash','policyVersion','readiness.review.v1'));
 select jsonb_object_agg(domain,jsonb_build_object('state',case when domain='propertyFacts'and jsonb_array_length(f->'property'->'amenities')=0 then'missing'when domain='integrations'and jsonb_array_length(caps)>0 then'needs_review'when domain in('units','assets','neighborhood')then'missing'else'ready'end,'approvalPolicy',case when domain in('identityContact','brand','legal')then'required'when domain='propertyFacts'or(domain='integrations'and jsonb_array_length(caps)>0)then'manager_override'else'advisory'end,'blocking',(domain='propertyFacts'and jsonb_array_length(f->'property'->'amenities')=0)or(domain='integrations'and jsonb_array_length(caps)>0),'reasons','[]'::jsonb,'sourceIds','[]'::jsonb))into reports from unnest(array['identityContact','brand','assets','propertyFacts','units','neighborhood','legal','integrations'])domain;
 select coalesce(jsonb_agg(jsonb_build_object('domain',k,'reasons',v->'reasons','sourceIds',v->'sourceIds','approvalPolicy',v->>'approvalPolicy')),'[]')into conflicts from jsonb_each(reports)e(k,v)where v->'blocking'='true';
 return jsonb_build_object('sourceHash',b->>'sourceHash','payload',p,'contentHash',public.knowledge_hash(p),'domains',reports,'unresolvedConflicts',conflicts,'sourceReferences','[]'::jsonb,'status',case when jsonb_array_length(conflicts)=0 then'ready'else'needs_review'end);
end$$;
create function pg_temp.review_input(i uuid,op text default'approve',allow_override boolean default false)returns jsonb language sql as $$select jsonb_build_object('operation',op,'snapshotId',i,'snapshotHash',public.knowledge_hash(to_jsonb(s)),'sourceHash',m.source_hash,'confirmed',true,'allowManagerOverride',allow_override,'reason','Review this exact saved readiness source evidence')from public.property_onboarding_snapshots s join public.readiness_source_manifests m on m.snapshot_id=s.id where s.id=i$$;
select pg_temp.check_it(pg_temp.read_check()->>'total'='0','empty readiness does not invent approval');
insert into st values('sources',pg_temp.read_check('{"kind":"sources"}'));
select pg_temp.check_it((select v->>'state'='ready'and v::text not like'%PRIVATE-FIXTURE%'and jsonb_array_length(v->'sources'->'contacts')=1 and not(v->'sources'->'integrations'->0?'credentials')from st where k='sources'),'complete source bundle omits secrets billing contacts and internal conversations');
insert into st values('build',pg_temp.build_input()),('calculation',pg_temp.calculation());
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000010',(select v from st where k='build'),(select v from st where k='calculation'))->>'status'='ready','build saves an unapproved exact source check');
select pg_temp.check_it((select status='ready'and approved_by is null and approval_action_attempt_id is null from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000010'),'building cannot automatically approve');
select pg_temp.check_it(pg_temp.read_check('{"kind":"active"}')->'snapshot'='null'::jsonb,'active reader does not serve unapproved drafts');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000010',(select v from st where k='build'))->>'state'='replayed','lost build reply replays without recomputation');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000010',pg_temp.build_input('["crm"]'))->>'state'='request_conflict','same identity different capability request held');
select pg_temp.check_it(pg_temp.read_check('{"kind":"snapshot","snapshotId":"ee610000-0000-4000-8000-000000000010"}')->'eligibility'->'canApprove'='true','complete current snapshot eligible');
insert into st values('approve',pg_temp.review_input('ee610000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='saved','explicit approval saved');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000011',(select v from st where k='approve'))->>'state'='replayed','lost approval replay');
select pg_temp.check_it((select status='approved'and approved_by='11111111-1111-1111-1111-111111111111'and approval_action_attempt_id='ee610000-0000-4000-8000-000000000011'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000010')and exists(select 1 from public.shared_jobs where id='ee610000-0000-4000-8000-000000000011')and exists(select 1 from public.shared_action_attempts where id='ee610000-0000-4000-8000-000000000011')and exists(select 1 from public.shared_approvals where id='ee610000-0000-4000-8000-000000000011'),'approval snapshot job attempt and reviewer evidence committed together');
select pg_temp.check_it(pg_temp.read_check('{"kind":"active"}')->'snapshot'->>'status'='approved','active reader returns the current approved snapshot');
select pg_temp.check_it(public.readiness_publication_snapshot('ee610000-0000-4000-8000-000000000001')->>'state'='ready','current approved publication snapshot available');
update public.integration_credentials set notes='Changed PRIVATE-FIXTURE'where id='ee610000-0000-4000-8000-000000000007';
select pg_temp.check_it((select status='approved'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000010'),'private notes do not invalidate public fact evidence');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000012',pg_temp.build_input('["crm"]'),pg_temp.calculation('["crm"]'))->>'status'='needs_review','new selected capability check requires review');
select pg_temp.check_it((select status='approved'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000010'),'private check leaves existing valid approval');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000013',pg_temp.review_input('ee610000-0000-4000-8000-000000000012'))->>'state'='override_required','warnings require explicit manager explanation');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000014',pg_temp.review_input('ee610000-0000-4000-8000-000000000012','approve',true))->>'state'='saved','exact warnings can be acknowledged');
select pg_temp.check_it((select status='stale'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000010'),'new approval supersedes earlier choice');
select pg_temp.check_it((select count(*)=1 from public.readiness_invalidations where snapshot_id='ee610000-0000-4000-8000-000000000010'),'supersession has system invalidation evidence');
insert into st values('priorReview',pg_temp.review_input('ee610000-0000-4000-8000-000000000012','withdraw'));
update public.properties set amenities=array['Changed supplied amenity']where id='ee610000-0000-4000-8000-000000000001';
select pg_temp.check_it((select status='stale'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000012'),'source mutation invalidates approved snapshot');
select pg_temp.check_it(pg_temp.read_check('{"kind":"active"}')->'snapshot'='null'::jsonb,'active reader withholds stale approval');
select pg_temp.check_it(public.readiness_publication_snapshot('ee610000-0000-4000-8000-000000000001')->>'state'='unavailable','stale evidence cannot serve publication');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000015',(select v from st where k='priorReview'))->>'state'='snapshot_changed','stale operator review held');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000016',pg_temp.build_input(),(select v from st where k='calculation'))->>'state'='sources_changed','late calculation cannot build against changed facts');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000017',pg_temp.build_input(),pg_temp.calculation())->>'state'='saved','new complete sources create a current check');
create function pg_temp.fail_activity()returns trigger language plpgsql as $$begin if new.property_id='ee610000-0000-4000-8000-000000000001'then raise exception 'Fixture action failure';end if;return new;end$$;
create trigger readiness_fixture_activity before insert on public.shared_action_events for each row execute function pg_temp.fail_activity();
select pg_temp.throws($q$select pg_temp.decide('ee610000-0000-4000-8000-000000000018',pg_temp.review_input('ee610000-0000-4000-8000-000000000017'))$q$,'activity failure rolls back all approval writes');
drop trigger readiness_fixture_activity on public.shared_action_events;
select pg_temp.check_it((select status='ready'from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000017')and not exists(select 1 from public.shared_jobs where id='ee610000-0000-4000-8000-000000000018')and not exists(select 1 from public.shared_action_attempts where id='ee610000-0000-4000-8000-000000000018')and not exists(select 1 from public.shared_approvals where id='ee610000-0000-4000-8000-000000000018'),'no partial job attempt approval or approved status');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000019',pg_temp.review_input('ee610000-0000-4000-8000-000000000017'))->>'state'='saved','fresh explicit approval still works');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000020',pg_temp.review_input('ee610000-0000-4000-8000-000000000017','withdraw'))->>'state'='saved','approval withdrawal retained');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000021',pg_temp.build_input(),pg_temp.calculation())->>'status'='ready','same current withdrawn facts can be rebuilt without automatic reapproval');
select pg_temp.check_it((select approved_by is null and approval_action_attempt_id is null from public.property_onboarding_snapshots where id='ee610000-0000-4000-8000-000000000017'),'rebuild clears current approval pointers but preserves prior decisions');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000022',pg_temp.review_input('ee610000-0000-4000-8000-000000000017','reject'))->>'state'='saved','explicit rejection retained');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000023',pg_temp.review_input('ee610000-0000-4000-8000-000000000017'))->>'state'='not_approvable','rejected snapshot must be rebuilt before review');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000024',jsonb_build_object('operation','cancel_unused','inputHash',repeat('c',64),'reason','Stop unused readiness request'))->>'state'='cancelled','unused cancellation retained');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000024',pg_temp.build_input(),pg_temp.calculation())->>'state'='decision_cancelled','unused cancellation fences late build');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000019',jsonb_build_object('operation','cancel_unused','inputHash',repeat('c',64),'reason','Check original approval'))->>'state'='replayed','unused cancellation cannot undo a saved approval');
select pg_temp.check_it(pg_temp.read_check('{"kind":"decision","decisionId":"ee610000-0000-4000-8000-000000000019"}')->>'snapshotId'='ee610000-0000-4000-8000-000000000017','exact saved decision recovery');
select pg_temp.check_it(pg_temp.read_check('{"kind":"history_detail","decisionId":"ee610000-0000-4000-8000-000000000019"}')::text not like'%PRIVATE-FIXTURE%','decision inspection contains only safe facts');
select pg_temp.throws($q$update public.property_onboarding_snapshots set status='approved'where id='ee610000-0000-4000-8000-000000000017'$q$,'raw adopted approval held');
select pg_temp.throws($q$update public.readiness_source_manifests set source_hash=repeat('z',64)where snapshot_id='ee610000-0000-4000-8000-000000000017'$q$,'source manifest immutable');
select pg_temp.throws($q$delete from public.readiness_decisions where id='ee610000-0000-4000-8000-000000000019'$q$,'decisions immutable');
select pg_temp.check_it(not has_table_privilege('authenticated','public.property_onboarding_snapshots','SELECT')and not has_function_privilege('authenticated','public.readiness_source_bundle(uuid)','EXECUTE'),'raw clients cannot bypass safe scoped reads');
update public.profiles set role='viewer'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_check()->>'canManage'='false'and pg_temp.decide('ee610000-0000-4000-8000-000000000025',pg_temp.build_input(),pg_temp.calculation())->>'state'='forbidden','viewer cannot build or approve');
update public.profiles set role='admin'where id='11111111-1111-1111-1111-111111111111';
insert into public.property_onboarding_snapshots(id,property_id,org_id,status,content_hash,snapshot_payload)values('ee610000-0000-4000-8000-000000000030','ee610000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','approved',repeat('f',64),'{"integrations":[{"id":"old","credentials":{"token":"PRIVATE-FIXTURE"},"notes":"PRIVATE-FIXTURE","platform":"hubspot"}],"contacts":[{"name":"PRIVATE-FIXTURE","contact_type":"billing"}],"brand":{"gemini_conversation_history":"PRIVATE-FIXTURE"},"property":{"settings":{"secret":"PRIVATE-FIXTURE"}}}');
select pg_temp.check_it(pg_temp.read_check('{"kind":"snapshot","snapshotId":"ee610000-0000-4000-8000-000000000030"}','ee610000-0000-4000-8000-000000000002')::text not like'%PRIVATE-FIXTURE%','older payloads are redacted on inspection');
select pg_temp.check_it(public.readiness_publication_snapshot('ee610000-0000-4000-8000-000000000002')->>'state'='unavailable','unrecorded legacy approval cannot serve as current evidence');
select pg_temp.check_it(pg_temp.read_check('{"kind":"snapshot","snapshotId":"ee610000-0000-4000-8000-000000000030"}')->>'state'='not_found','cross-property snapshot inspection refused');
insert into public.property_onboarding_snapshots(id,property_id,org_id,status,content_hash)select md5('readiness-page:'||n)::uuid,'ee610000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','draft',public.knowledge_hash(to_jsonb(n))from generate_series(1,1005)n;
select pg_temp.check_it(pg_temp.read_check('{"offset":1000}','ee610000-0000-4000-8000-000000000002')->>'total'='1006'and jsonb_array_length(pg_temp.read_check('{"offset":1000}','ee610000-0000-4000-8000-000000000002')->'items')=6,'complete native snapshot paging exceeds REST limit');
insert into public.property_contacts(id,property_id,contact_type,name,email)select md5('readiness-contact:'||n)::uuid,'ee610000-0000-4000-8000-000000000002','secondary','Fixture contact '||n,'fixture@example.invalid'from generate_series(1,1005)n;
select pg_temp.check_it(jsonb_array_length(pg_temp.read_check('{"kind":"sources"}','ee610000-0000-4000-8000-000000000002')->'sources'->'contacts')=1005,'source collection includes all native contacts');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee610000-0000-4000-8000-000000000001'and(training_eligible or request::text like'%PRIVATE-FIXTURE%')),'semantic history private and training excluded');

select pg_temp.check_it(public.readiness_safe_brand('{}')='{}','empty safe brand remains exact');
select pg_temp.check_it(public.read_forgestudio_source_record('ee610000-0000-4000-8000-000000000002','onboarding','ee610000-0000-4000-8000-000000000030')is null,'ForgeStudio cannot consume a legacy approval without current source evidence');
insert into public.readiness_decisions(id,property_id,org_id,actor_id,snapshot_id,kind,input,input_hash,before_state,after_state,result)select md5('readiness-history:'||n)::uuid,'ee610000-0000-4000-8000-000000000002','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','ee610000-0000-4000-8000-000000000030','built','{"reason":"Retained history fixture"}',repeat('d',64),'{}','{}','{}'from generate_series(1,1005)n;
select pg_temp.check_it(pg_temp.read_check('{"kind":"history","offset":1000}','ee610000-0000-4000-8000-000000000002')->>'total'='1005'and jsonb_array_length(pg_temp.read_check('{"kind":"history","offset":1000}','ee610000-0000-4000-8000-000000000002')->'items')=5,'complete decision history exceeds REST cap');
select pg_temp.check_it(pg_temp.read_check('{"kind":"history","expectedHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}','ee610000-0000-4000-8000-000000000002')->>'state'='history_changed','changed history page held');
update public.properties set address='{"street":"1 Lane","state":"XX"}'where id='ee610000-0000-4000-8000-000000000001';
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000026',pg_temp.build_input(),pg_temp.calculation())->>'state'='saved','incomplete source check remains reviewable as evidence');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000027',pg_temp.review_input('ee610000-0000-4000-8000-000000000026','approve',true))->>'state'='not_approvable','native requirements reject incorrectly optimistic calculation and manager override');
select pg_temp.check_it(not exists(select 1 from public.shared_approvals where id='ee610000-0000-4000-8000-000000000027'),'failed hard qualification creates no approval evidence');
insert into public.organizations(id,name)values('ee610000-0000-4000-8000-000000000099','Readiness transfer SQL fixture');
set local session_replication_role=replica;
update public.properties set org_id='ee610000-0000-4000-8000-000000000099'where id='ee610000-0000-4000-8000-000000000001';
set local session_replication_role=origin;
select pg_temp.check_it(pg_temp.read_check()->>'state'='forbidden','old organization cannot inspect transferred readiness');
update public.profiles set org_id='ee610000-0000-4000-8000-000000000099'where id='11111111-1111-1111-1111-111111111111';
select pg_temp.check_it(pg_temp.read_check()->>'state'='scope_changed','new organization cannot inherit old private readiness decisions');
select pg_temp.check_it(pg_temp.decide('ee610000-0000-4000-8000-000000000028',pg_temp.build_input(),pg_temp.calculation())->>'state'='scope_changed','transferred readiness cannot be silently relabeled');
select n as passed_assertions from assertion_count;
ROLLBACK;
